  const allElements = Array.from(document.querySelectorAll('*'));
  const selectVoiceHeading = allElements.find(el => el.textContent?.trim() === 'Select a voice');
  if (!selectVoiceHeading) return "No 'Select a voice' heading found";

  // Find container
  let container = selectVoiceHeading.parentElement;
  for (let i = 0; i < 4; i++) {
    if (container && container.children.length > 2) break;
    if (container) container = container.parentElement;
  }

  // Let's get all buttons / cards in container
  const buttons = Array.from(container?.querySelectorAll('button, [role="button"], a') || []);
  return {
    containerText: container?.innerText?.slice(0, 2000),
    buttons: buttons.map(b => b.innerText?.trim()).filter(Boolean)
  };
});

