// Let's inspect the exact cards under "Meet the AI voices loved by millions of creators"
const voiceCardsData = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('*')).filter(el => {
    return el.children.length === 0 && (
      el.textContent?.trim() === 'Haytham' ||
      el.textContent?.trim() === 'Amelia' ||
      el.textContent?.trim() === 'Otto' ||
      el.textContent?.trim() === 'Sara Martin' ||
      el.textContent?.trim() === 'Artem Lebedev' ||
      el.textContent?.trim() === 'Otani' ||
      el.textContent?.trim() === 'Peter'
    );
  });

  return cards.map(c => {
    let parent = c.parentElement;
    for (let i = 0; i < 3; i++) {
      if (parent && parent.innerText.length > 50) break;
      if (parent) parent = parent.parentElement;
    }
    return {
      voice: c.textContent?.trim(),
      cardText: parent?.innerText?.trim()
    };
  });
});

